Definition recycle_prim1_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem)
    (lo CA c p mhdr u rz n actx b1 TH : Z) : machine_state -> Prop :=
